# Initializing the SQLite schema on every widget click makes Streamlit reruns
# feel heavier than they need to. Do it once per app process instead.
@st.cache_resource(show_spinner=False)
def _initialize_database_once():
    init_db()
    return True


_initialize_database_once()


@st.cache_data(show_spinner=False)
def image_to_data_uri(path: Path) -> str:
    """Return a local image as a data URI so CSS can crop/size it consistently."""
    if not path.exists():
        return ""
    mime_type = mimetypes.guess_type(path.name)[0] or "image/jpeg"
    encoded = base64.b64encode(path.read_bytes()).decode("utf-8")
    return f"data:{mime_type};base64,{encoded}"


