def build_demo_catalog_output():
    """Create a deterministic SKU-level demo result without calling the AI engine."""
    output_rows = []
    missing_counts = {}
    total_readiness = 0

    for row in DEMO_CATALOG_ROWS:
        missing = []
        for field in DEMO_REQUIRED_FIELDS:
            if field == "Business Name":
                value = DEMO_VENDOR_NAME
            else:
                value = row.get(field)
            if value is None or str(value).strip() == "":
                missing.append(field)
                missing_counts[field] = missing_counts.get(field, 0) + 1

        readiness = round(((len(DEMO_REQUIRED_FIELDS) - len(missing)) / len(DEMO_REQUIRED_FIELDS)) * 100)
        total_readiness += readiness
        output_rows.append({
            "SKU": row["SKU"],
            "Product Name": row["Product Name"],
            "Status": "Publish Ready" if not missing else "Needs Attention",
            "Readiness %": readiness,
            "Missing Fields": ", ".join(missing) if missing else "—",
            "Price": row.get("Price"),
            "Inventory": row.get("Inventory"),
        })

    ready_count = sum(1 for row in output_rows if row["Status"] == "Publish Ready")
    avg_readiness = round(total_readiness / len(output_rows))
    unique_gaps = list(missing_counts.keys())

    analysis = {
        "business_name": DEMO_VENDOR_NAME,
        "category": "APPAREL",
        "location": "Brooklyn, NY",
        "contact": "demo@cherrythread.example",
        "social_media": "@cherrythread_demo",
        "information_found": [
            "20 SKU rows detected from the demo catalog",
            "Mapped product name, category, price, size, color, fabric, fit and care fields",
            f"{ready_count} of {len(output_rows)} SKUs are publish ready",
            "Inventory was preserved as useful non-blocking catalog information",
        ],
        "products_found": [row["Product Name"] for row in DEMO_CATALOG_ROWS[:6]] + ["… 14 more SKUs"],
        "required_gaps": unique_gaps,
        "optional_gaps": [],
        "follow_up_questions": [
            f"Provide {field} for {count} SKU{'s' if count != 1 else ''}."
            for field, count in missing_counts.items()
        ],
        "readiness_score": avg_readiness,
        "status": "Publish Ready" if ready_count == len(output_rows) else ("Almost Ready" if avg_readiness >= 80 else "Needs Information"),
    }

    return output_rows, analysis


