def get_or_create_marketplace():
    marketplace_name = st.session_state.company_name.strip()

    if not marketplace_name:
        return None

    marketplaces = get_marketplaces()

    for marketplace in marketplaces:
        if marketplace["name"].lower() == marketplace_name.lower():
            return marketplace["marketplace_id"]

    return create_marketplace(marketplace_name)

