    marketplace_gmv = sum(v["gmv"] for v in demo_vendors)
    scale = marketplace_gmv / sum(daily_gmv)
    daily_gmv = [round(x * scale) for x in daily_gmv]
    daily_gmv[-1] += marketplace_gmv - sum(daily_gmv)

